import { getSupabaseClient } from '../common/supabase-client';
import { campaignRealtimeFilters, parseCampaignId } from '../common/campaign-filters';

let nextId = 1;

/**
 * Calls `onChange` (debounced) whenever a donation to this campaign, or one rolled up into it,
 * changes (the same two filtered Realtime subscriptions the overlay uses). Deletions cannot be
 * filtered by Postgres, so a full refund is caught by an unfiltered DELETE listener, as the
 * overlay does; refunds are rare, so the extra refetches are negligible.
 *
 * Returns a function that stops watching. Without a campaign id there is nothing to watch.
 */
export function watchCampaignDonations(campaignId: string | null, onChange: () => void): () => void {
  const id = parseCampaignId(campaignId); // throws on anything but a UUID: it goes into a filter
  if (!id) return () => {};
  campaignId = id;
  const supabase = getSupabaseClient();
  let timer: ReturnType<typeof setTimeout> | undefined;
  const changed = () => {
    clearTimeout(timer);
    timer = setTimeout(onChange, 250);
  };

  const channel = supabase.channel(`rg-campaign-donations-${campaignId}-${nextId++}`);
  for (const filter of campaignRealtimeFilters(campaignId)) {
    channel.on('postgres_changes', { event: '*', schema: 'public', table: 'donations', filter }, changed);
  }
  channel.on('postgres_changes', { event: 'DELETE', schema: 'public', table: 'donations' }, changed);
  channel.subscribe();

  return () => {
    clearTimeout(timer);
    void supabase.removeChannel(channel);
  };
}
