import { BaseElement } from '../common/base-element';
import { fetchProgress } from './api';
import { watchCampaignDonations } from './live';
import { progressBarHtml } from './progress-bar-html';
import { progressStyles } from './styles/progress';

/**
 * <rg-progress-bar slug="my-campaign" campaign-id="…">: raised so far against the goal.
 * With `campaign-id` it also refreshes as soon as a donation to the campaign (or one rolled up
 * into it) is recorded. Shows nothing if the campaign cannot be read.
 */
export class RgProgressBar extends BaseElement {
  static get observedAttributes(): string[] {
    return ['slug', 'campaign-id'];
  }

  private stopWatching: (() => void) | undefined;
  private started = false;

  constructor() {
    super(`:host { display: block; }\n${progressStyles}`);
  }

  connectedCallback(): void {
    this.start();
  }

  disconnectedCallback(): void {
    this.started = false;
    this.stopWatching?.();
    this.stopWatching = undefined;
  }

  attributeChangedCallback(): void {
    if (this.started) this.start();
  }

  private start(): void {
    this.started = true;
    this.stopWatching?.();
    const slug = this.getAttribute('slug');
    if (!slug) {
      this.setHtml('');
      return;
    }
    this.setHtml('<div class="pb-wrap"><div class="pb-track"><div class="pb-fill" style="width:0%"></div></div><div class="pb-label">Loading…</div></div>');

    const refresh = () => {
      fetchProgress([slug])
        .then((rows) => {
          this.setHtml(rows.length ? progressBarHtml(rows[0].raised_cents, rows[0].goal_cents) : '');
        })
        .catch(() => {
          this.setHtml('');
        });
    };
    refresh();
    try {
      this.stopWatching = watchCampaignDonations(this.getAttribute('campaign-id'), refresh);
    } catch (err) {
      console.error('Progress bar: live updates are off.', err);
    }
  }
}

if (!customElements.get('rg-progress-bar')) customElements.define('rg-progress-bar', RgProgressBar);
